// pxl-tool/spec/cmd.rs

//! pixelet's command table, generated by xpute's generator (xpute-tool
//! `spec::cmd::table_outputs`): handed the table and where its code goes, it
//! writes the client's TypeScript and the kernel's Rust.

use xpute_tool::spec::cmd::{table_outputs, Table};

use super::Output;
use crate::root;

const JSON: &str = "spec/client/kernel/domain/control/cmd.json";

pub fn outputs() -> Result<Vec<Output>, String> {
    let json = root().join(JSON);
    let table = Table {
        json: &json.to_string_lossy(),
        ts: "ts/client/src/abi/cmd.spec.ts",
        rs: "rust/client/kernel/src/domain/control/cmd.spec.rs",
        json_shown: JSON,
        ts_shown: "@pxl/client/abi/cmd.spec.ts",
        rs_shown: "pxl-kernel/domain/control/cmd.spec.rs",
        number: "xpute_guest::abi::number",
        program: None,
        event: Some("xpute_guest::ipc::door"),
        port: None,
    };
    Ok(table_outputs(&table)?
        .into_iter()
        .map(|o| Output::new(&o.path, o.text))
        .collect())
}
